dtsPropsFor.AttestationBadge:
/**
 * Current state of the enclave attestation handshake. The badge renders a
 * distinct colour and label for each `kind` (pending / failed / verified).
 */
status:
  | { kind: "idle" | "verifying" | "warming" }
  | { kind: "failed"; code: string; detail: string }
  | { kind: "verified"; signatureVerified: boolean };
/** Called when the user clicks "Retry" on a failed badge. */
onRetry: () => void;

dtsPropsFor.PassphraseScreen:
/**
 * The local, client-side encrypted journal (IndexedDB-backed). The screen
 * calls `hasJournal()` to choose between unlock and create, and `unlock()`
 * to stretch the passphrase (Argon2id) into the journal's AES key.
 */
db: {
  hasJournal(): Promise<boolean>;
  unlock(passphrase: string): Promise<{ key: CryptoKey }>;
  importJournal(bytes: Uint8Array): Promise<void>;
};
/** Called with the derived journal key once the passphrase unlocks it. */
onUnlocked: (key: CryptoKey) => void;

dtsPropsFor.ChatPane:
/** The unlocked journal the client-side tools read and write through. */
db: unknown;
/** The AES key for the unlocked journal. */
journalKey: CryptoKey;
/** The shared, verified enclave session: attestation status + pinned HPKE key. */
session: {
  status:
    | { kind: "idle" | "verifying" | "warming" }
    | { kind: "failed"; code: string; detail: string }
    | { kind: "verified"; signatureVerified: boolean; hpkePublicKey: unknown };
  /** Re-run attestation (e.g. after the enclave restarts). */
  verify: () => Promise<void>;
};

dtsPropsFor.JournalView:
/** The unlocked, client-side encrypted journal (IndexedDB-backed). */
db: unknown;
/** The AES key for the unlocked journal. */
journalKey: CryptoKey;
/** Called to lock the journal and return to the passphrase screen. */
onLock: () => void;
